BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-i-q31', '10. AI倫理・AIガバナンス',
   'AIに関する国内外のガイドラインの多くは、罰則を伴う法律ではなく、拘束力のない指針として作られている。このような指針の性質を表す語はどれか。',
   NULL::text,
   '["ソフトロー（法的拘束力を持たない指針や自主規制）", "ハードロー（違反に罰則が伴う法律や条例）", "業界標準規格（製品の仕様をそろえるための取り決め）", "努力義務（法律の中で「〜するよう努める」と定める規定）"]',
   0,
   '[0]',
   'single',
   '{"asked": "拘束力のない指針という性質を表す語を問う設問。", "point": "罰則が無く拘束力を持たない指針ならソフトロー。破ると罰則がある法律はハードロー。", "kid": "守ってほしいけれど、破っても罰則は無いルールのこと。", "eg": "校則に例えると、ハードローは「破ると停学になる規則」、ソフトローは「守ってほしいけれど破っても罰は無いマナー」にあたる。", "terms": [["ソフトロー", "破っても罰則がない、けれど守ってほしいという指針"], ["ハードロー", "破ると罰則がある法律"], ["ガイドライン", "国や団体が示す望ましい行動の手引き"]], "think": "なぜAI分野ではソフトローが選ばれやすいのかがカギ。AI技術は変化が速いが、法律(ハードロー)は国会での審議などを経るため作るのに時間がかかり、施行された頃には技術の状況が変わってしまいやすい。一方ソフトローは指針を出すだけなので早く作れて、状況に応じてすぐ書き換えられる。だから変化の速いAI分野では、まずソフトローで様子を見て、本当に必要な部分だけ後から法律にするという進め方が採られやすい。", "vs": "ハードローとの違いは罰則の有無。業界標準規格は製品の技術仕様をそろえる取り決めで、行動の指針そのものを表す語ではない点が違う。", "why_asked": "日本のAI戦略はソフトロー中心という一次資料の記述に基づく頻出論点。", "usecase": "新しい技術のルール整備で、法律を作るまでの「つなぎ」として先に指針を出す場面。", "opt": ["正解。ソフトローは法的な強制力を持たないが、望ましい行動を示す指針のこと。AIガイドラインの多くがこの形をとる。", "ハードローは罰則を伴う法律や条例のこと。AI分野では制定に時間がかかるため、指針より数が少ない。", "業界標準規格は主に製品や技術の仕様をそろえるための取り決めで、行動指針そのものを表す語ではない。", "努力義務は法律の中に置かれる規定の一種で、指針の性質そのものを表す分類名ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">AIガイドラインの位置づけ</text>\n<rect x=\"20\" y=\"30\" width=\"140\" height=\"85\" rx=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n<text x=\"90\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c47070\">ハードロー</text>\n<text x=\"90\" y=\"72\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">罰則あり</text>\n<text x=\"90\" y=\"90\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">変更に時間が</text>\n<text x=\"90\" y=\"104\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">かかる</text>\n<rect x=\"180\" y=\"30\" width=\"140\" height=\"85\" rx=\"6\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<text x=\"250\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" fill=\"#6ab08d\">ソフトロー</text>\n<text x=\"250\" y=\"72\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">罰則なし</text>\n<text x=\"250\" y=\"90\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">柔軟にすぐ</text>\n<text x=\"250\" y=\"104\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">見直せる</text>\n</svg>"}'),
  ('g-kentei-i-q32', '10. AI倫理・AIガバナンス',
   'AIの規制を考えるとき、想定される害の大きさによって規制の重さを変える考え方がある。この考え方はどれか。',
   NULL::text,
   '["リスクベースアプローチ（危険度に応じて規制の強さを段階的に変える考え方）", "ゼロリスクアプローチ（あらゆる危険性を一律にすべて禁止しようとする考え方）", "自主規制アプローチ（当事者同士の任意の取り組みだけに委ねる考え方）", "事後対応アプローチ（問題が実際に起きてから対処を検討する考え方）"]',
   0,
   '[0]',
   'single',
   '{"asked": "危険度に応じて規制の重さを変える考え方の名前を問う設問。", "point": "危険度が高い用途ほど義務を重くするならリスクベースアプローチ。", "kid": "危ない使い方には厳しいルール、そうでない使い方には軽いルール、と使い道ごとにルールの重さを変える考え方。", "eg": "遊園地の乗り物に例えると、ジェットコースターは安全ベルトも係員のチェックも厳重だが、メリーゴーラウンドはゆるいルールで済む。乗り物の危険度によって安全対策の重さを変えているのと同じ発想。", "terms": [["リスクベースアプローチ", "危険度で規制の重さを変える考え方"], ["EU AI Act", "この考え方を採用したEUの規制の例として挙げられることが多い法規制"]], "think": "なぜ一律規制ではなく段階分けが選ばれるのかがカギ。すべてのAI用途を同じ重さで規制すると、危険が小さい用途まで重い義務を背負うことになり開発が止まりやすくなる一方、本当に危険な用途への対応が薄くなる恐れもある。そこで用途をいくつかの危険度の段階に分け、危険度が高い段ほど義務を重くすることで、安全の確保と技術の発展を両立させようとする。だから一律規制ではなく段階分けが選ばれる。", "vs": "EU AI Actはこの考え方を採用した規制の例として挙げられることが多いが、リスクベースアプローチという考え方自体は特定の法律の名前ではない。あらゆる危険性を一律に禁止するゼロリスクアプローチとは真逆の発想。", "why_asked": "国内外のガイドラインに共通する重要な考え方として頻出。", "usecase": "AI利用のルールを作るとき、用途を危険度ごとに分類して義務の重さを決める場面。", "opt": ["正解。リスクベースアプローチは、想定される危険の大きさに応じて規制の重さを段階的に変える考え方。", "ゼロリスクアプローチは、危険性がある用途をすべて一律に禁止しようとする考え方で、開発の余地を大きく狭めてしまう。", "自主規制アプローチは、法律や指針を作らず当事者の任意の取り組みだけに委ねる考え方で、実効性にばらつきが出やすい。", "事後対応アプローチは、あらかじめ規制を作らず問題が起きてから対処を検討する考え方で、被害の予防にはつながりにくい。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">危険度で規制の重さを変える</text>\n<rect x=\"130\" y=\"24\" width=\"80\" height=\"22\" rx=\"3\" fill=\"#c47070\"/>\n<text x=\"170\" y=\"39\" text-anchor=\"middle\" font-size=\"10\" fill=\"#141720\">禁止</text>\n<rect x=\"95\" y=\"50\" width=\"150\" height=\"22\" rx=\"3\" fill=\"#c9a04a\"/>\n<text x=\"170\" y=\"65\" text-anchor=\"middle\" font-size=\"10\" fill=\"#141720\">厳格な義務</text>\n<rect x=\"60\" y=\"76\" width=\"220\" height=\"22\" rx=\"3\" fill=\"#3b82f6\"/>\n<text x=\"170\" y=\"91\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">軽い義務(透明性など)</text>\n<rect x=\"20\" y=\"102\" width=\"300\" height=\"22\" rx=\"3\" fill=\"#2a2f3f\"/>\n<text x=\"170\" y=\"117\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">義務なし</text>\n<text x=\"170\" y=\"135\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">危険度: 高（上）→低（下）</text>\n</svg>"}'),
  ('g-kentei-i-q33', '10. AI倫理・AIガバナンス',
   '各国・各団体のAIガイドラインを比べると、表現は違っても共通して掲げられている柱がある。次のうち、そうした共通の柱として最も適切なものはどれか。',
   NULL::text,
   '["人間中心・公平性・透明性・アカウンタビリティといった価値原則", "処理速度・省電力・低コスト・小型化といった、製品ごとの性能面の指標", "市場シェア・売上高・利用者数といった、企業ごとの事業面の指標", "プログラミング言語・フレームワーク・開発環境といった技術選定の項目"]',
   0,
   '[0]',
   'single',
   '{"asked": "各国ガイドラインに共通する柱として最も適切なものを問う設問。", "point": "各国ガイドラインに共通するのは性能や事業の数字ではなく、人間中心・公平性・透明性・アカウンタビリティといった価値観の柱。", "kid": "国や団体ごとに書き方は違っても、「人を中心に置く」「公平である」「中身が分かるようにする」「何かあったら誰が責任を持つか決めておく」という考え方は共通して出てくる。", "eg": "各国が別々に作った憲法や規範でも「人の命を大事にする」といった価値観は共通して書かれているのに似ている。表現の言葉は違っても、根っこの考え方は重なる。", "terms": [["アカウンタビリティ", "問題が起きたとき誰が説明・責任を負うかをはっきりさせておくこと"], ["価値原則", "各ガイドラインに共通して掲げられる考え方の柱"]], "think": "なぜ各国のガイドラインで表現が違うのに柱が重なるのかがカギ。それぞれの国や団体は独自に議論して指針を作ってはいるが、AIが人の生活や権利に与える影響という論点自体はどの国でも共通している。だから行き着く先の柱、つまり人間中心・公平性・透明性・アカウンタビリティが、表現は違っても自然と似通ってくる。", "vs": "性能指標や事業指標は各企業・各製品ごとに違ってよいもので、ガイドラインが共通して掲げる「価値観」とは性質が異なる。", "why_asked": "個々の指針の細部より、共通する骨組みを理解しているかを問う定番論点。", "usecase": "自社のAI倫理方針を作るとき、各国ガイドラインを見比べてまず共通の柱を土台にする場面。", "opt": ["正解。人間中心・公平性・透明性・アカウンタビリティは、各国・各団体のガイドラインに表現は違っても共通して掲げられる価値原則。", "処理速度・省電力・低コスト・小型化は個々のAI製品の性能面の指標で、ガイドラインが共通して掲げる価値原則ではない。", "市場シェア・売上高・利用者数は個々の企業の事業面の指標で、ガイドラインが共通して掲げる価値原則ではない。", "プログラミング言語・フレームワーク・開発環境は技術選定の項目で、ガイドラインが共通して掲げる価値原則ではない。"]}'),
  ('g-kentei-i-q34', '10. AI倫理・AIガバナンス',
   'システムの設計を終えてから後付けでプライバシー対策を足すのではなく、企画・設計の最初の段階からプライバシーへの配慮を組み込んでおく考え方はどれか。',
   NULL::text,
   '["プライバシー・バイ・デザイン（設計の最初からプライバシーへの配慮を組み込む考え方）", "セキュリティパッチ（サービス公開後に見つかった不具合を後から修正していく更新プログラム）", "品質保証テスト（完成した製品を出荷する前に検査して問題がないか確かめていく工程）", "利用者アンケート（サービスを提供した後で利用者から感想や要望を集めていく調査活動）"]',
   0,
   '[0]',
   'single',
   '{"asked": "設計の最初からプライバシーへの配慮を組み込む考え方の名前を問う設問。", "point": "後付けではなく設計の入口から配慮を組み込むならプライバシー・バイ・デザイン。", "kid": "「あとで直せばいい」ではなく、最初の設計図を描く時点で「ここは配慮しておこう」と決めておく考え方。", "eg": "家を建てるとき、完成してから防犯のために鍵を付け足すのではなく、最初の設計図の段階で「玄関はここ」「鍵はこの位置」と決めておくのに似ている。", "terms": [["プライバシー・バイ・デザイン", "設計の最初からプライバシーへの配慮を組み込む考え方"]], "think": "なぜ後付けでは足りないのかがカギ。システムが出来上がってからプライバシーへの配慮を足そうとすると、データの集め方や保存の仕方といった根っこの仕組みまで作り直す必要が出てきてコストが跳ね上がり、直しきれない部分が残ってしまう。最初の設計段階で配慮を組み込んでおけば、仕組みそのものに配慮が織り込まれ、後から穴を塞ぐより確実に守れる。だから設計の入口で組み込むという発想が重視される。", "vs": "セキュリティ・バイ・デザインは「安全」を最初から組み込む考え方で、配慮する対象が「プライバシー」である点が今回の語と違う（隣接する考え方は別の問で扱う）。", "why_asked": "「後付けではなく最初から」という設計思想を理解しているかを問う定番論点。", "usecase": "新しいサービスの企画段階で、データの集め方や保存の仕方をあらかじめ配慮した形で設計する場面。", "opt": ["正解。プライバシー・バイ・デザインは、企画・設計の最初の段階からプライバシーへの配慮を組み込んでおく考え方。", "セキュリティパッチは、公開後に見つかった不具合を後から修正する更新のことで、最初の設計段階の話ではない。", "品質保証テストは、完成した製品を出荷前に検査する工程のことで、設計の最初から配慮を組み込む考え方そのものではない。", "利用者アンケートは、サービス提供後に感想や要望を集める調査のことで、設計段階の考え方とは別物。"]}'),
  ('g-kentei-i-q35', '10. AI倫理・AIガバナンス',
   '店舗に設置したカメラの映像をAIで解析して来店者の行動分析に使う場合、あらかじめ撮影の目的をカメラの近くに掲示するなど、事業者が留意すべき事項をまとめた指針はどれか。',
   NULL::text,
   '["カメラ画像利活用ガイドブック（カメラ画像をAIで解析して使う事業者向けの留意事項をまとめた指針）", "AI・データの利用に関する契約ガイドライン（AI開発を外部に頼むときの契約の進め方をまとめた指針）", "プライバシー・バイ・デザイン（設計の最初の段階から配慮を組み込む考え方そのもの）", "品質マネジメントの国際規格（製品やサービスの品質管理の手順を定めた規格）"]',
   0,
   '[0]',
   'single',
   '{"asked": "カメラ画像をAIで使う事業者向けの留意事項をまとめた指針の名前を問う設問。", "point": "店舗カメラの映像をAIで使う場面での留意事項ならカメラ画像利活用ガイドブック。", "kid": "店のカメラ映像をAIで解析して使うとき、「撮っていることをちゃんと知らせているか」「何のために使うか」を事業者が確認するためのチェックリストのようなもの。", "eg": "図書館の張り紙で「防犯のため撮影しています」と書いてあるのと同じ発想。何のために撮っているかを先に知らせておくことで、来館者が納得できる。", "terms": [["カメラ画像利活用ガイドブック", "店舗カメラの映像をAIで使う事業者向けの留意事項をまとめた指針"]], "think": "なぜ告知や目的の限定が求められるのかがカギ。カメラで撮られている側は、何のために使われるか分からないまま行動を見られると不安を感じる。あらかじめ何のために撮るかを示し、その範囲でしか使わないと決めておくことで、撮られる側の納得感を確保しつつ、事業者もデータをどこまで使ってよいかの線引きができる。", "vs": "AI・データの利用に関する契約ガイドライン（既出）は開発を外部に頼む場面の指針で対象が違う。プライバシー・バイ・デザインは考え方そのもの、今回の語はカメラ画像という特定の場面向けの具体的な指針。", "why_asked": "プライバシーの論点をAI倫理として問う代表例として頻出。", "usecase": "店舗にAIカメラを導入するとき、掲示の仕方や解析範囲を検討する場面。", "opt": ["正解。カメラ画像利活用ガイドブックは、店舗カメラの映像をAIで解析して使う事業者向けに留意事項をまとめた指針。", "AI・データの利用に関する契約ガイドラインは、AI開発を外部に頼むときの契約の進め方をまとめた指針で、対象の場面が違う。", "プライバシー・バイ・デザインは、設計の最初の段階から配慮を組み込む考え方そのもので、カメラ画像に特化した具体的な指針ではない。", "品質マネジメントの国際規格は、製品やサービスの品質管理の手順を定めた規格で、プライバシーの留意事項をまとめたものではない。"]}'),
  ('g-kentei-i-q36', '10. AI倫理・AIガバナンス',
   'AIの判定について「グループ間で正解率をそろえる」「グループ間で誤って不利に判定する割合をそろえる」など、公平性には複数の定義があり、状況によっては同時にすべてを満たせないことがある。この考え方として最も適切なものはどれか。',
   NULL::text,
   '["公平性の定義は一つに決まらず複数の基準が並び立ち、条件によっては同時に満たせないことがある", "公平性は正解率を100%にできるだけ近づければ、それだけで自動的に達成されるものである", "公平性はセンシティブ属性をモデルへの入力からあらかじめ取り除けば、それだけで常に達成される", "公平性は決まった唯一の計算式によって、誰にでも同じように機械的に判定できるものである"]',
   0,
   '[0]',
   'single',
   '{"asked": "公平性の定義が複数あり同時には満たせないことがあるという考え方を問う設問。", "point": "公平性は一つの物差しではなく、どの基準を優先するかで結論が変わりうる。", "kid": "「公平」と言っても測り方はいくつもあって、あるやり方で公平にすると別のやり方では公平でなくなることがある、というちょっとやっかいな話。", "eg": "クラスでお菓子を配るとき、「全員に同じ数を配る」公平さと、「お腹をすかせている人に多く配る」公平さは、どちらも「公平」と呼べるが同時には成立しない。公平の物差しは一つではない。", "terms": [["公平性の定義", "グループ間で何をそろえるかによって複数ある、公平さの測り方"]], "think": "なぜ複数の定義が両立しないことがあるのかがカギ。「グループ間で正解率をそろえる」ことと「グループ間で誤って不利に判定する割合をそろえる」ことは、それぞれ別の量に注目した基準である。グループの中身（実際に条件を満たす人の割合など）がグループ間で異なると、片方をぴったり満たそうとするともう片方がずれてしまう。だから「公平にする」と一言で言っても、どの基準を優先するかを先に決めないと議論がかみ合わない。", "vs": "センシティブ属性を入力から取り除けば解決するという単純な話ではない（別の項目が代わりに推測させてしまう問題は別の設問で扱う）。正解率を上げることと公平性は別の軸で、精度が高くても不公平な判定は起こりうる。", "why_asked": "公平性を単一の指標で語ってしまう誤解を正す、この分野の核心論点。", "usecase": "採用や与信の判定AIを設計するとき、どの公平性の基準を優先するかを関係者で先に議論する場面。", "opt": ["正解。公平性の定義は一つに決まらず複数の基準が並び立ち、条件によっては同時に満たせないことがある。", "正解率を100%に近づければ公平性の問題も自動的に解決するわけではない。正解率が高くても、グループ間で不利な誤り方に偏りが残ることがある。", "センシティブ属性を入力から取り除いても、他の項目がその属性を推測させてしまい偏りが残ることがあるため、常に達成できるわけではない。", "公平性を機械的に判定する唯一の計算式は無く、どの基準を採るかは状況に応じて人が判断する必要がある。"]}'),
  ('g-kentei-i-q37', '10. AI倫理・AIガバナンス',
   '性別のようなセンシティブ属性をモデルへの入力から取り除いても、居住地域や購買履歴など別の項目がその属性を強く推測させてしまい、結果的に偏った判定が残ることがある。このとき別の項目が果たしている役割を指す語はどれか。',
   NULL::text,
   '["代理変数（取り除いた属性の代わりに、その属性を強く推測させてしまう別の項目）", "特徴量エンジニアリング（予測に効きやすい項目を人が設計・加工していく作業）", "交絡因子（原因と結果の両方に影響し、見せかけの関係を生んでしまう第三の要因）", "ハイパーパラメータ（学習を始める前に人があらかじめ設定する調整用の値）"]',
   0,
   '[0]',
   'single',
   '{"asked": "取り除いた属性の代わりに推測を可能にする項目の名前を問う設問。", "point": "消した属性の身代わりになって推測を可能にする項目なら代理変数。", "kid": "「性別」を消しても、「よく買う商品」や「住んでいる場所」がこっそり性別を言い当ててしまい、結局偏りが残ってしまう。その「こっそり言い当ててしまう項目」のこと。", "eg": "テストでカンニングを禁止して答案用紙の名前欄を隠しても、筆跡でだいたい誰の答案か分かってしまうのに似ている。直接の手がかりを消しても、別の手がかりが残っていれば意味がない。", "terms": [["代理変数", "消した属性の代わりにその属性を推測させてしまう項目"], ["センシティブ属性", "差別につながりうるとして慎重な扱いが求められる属性"]], "think": "なぜセンシティブ属性を消すだけでは不十分なのかがカギ。現実のデータでは、性別のような属性と、居住地域や購買履歴のような他の項目が互いに強く関連していることが多い。属性そのものを入力から消しても、関連の強い他の項目が残っていれば、モデルはその項目を通じて属性をほぼ推測でき、偏った判定という結果は変わらない。だから「入力から消す」だけでは公平性の問題を解決したことにならない。", "vs": "交絡因子（因果推論の概念）とは役割が異なる。交絡因子は原因と結果の両方に影響して見せかけの関係を作る第三の要因で、代理変数は「消した属性の身代わりになって推測を可能にする項目」という別の意味。", "why_asked": "公平性対策の落とし穴として、属性を消すだけでは足りない点を理解しているかを問う。", "usecase": "採用AIから性別欄を削除しても偏りが残っていないか、他の項目との関連を点検する場面。", "opt": ["正解。代理変数は、取り除いた属性の代わりに、その属性を強く推測させてしまう別の項目のこと。", "特徴量エンジニアリングは、予測に効きやすい項目を人が設計・加工する作業のことで、代理変数という現象そのものを指す語ではない。", "交絡因子は、原因と結果の両方に影響し見せかけの関係を生む第三の要因のことで、代理変数とは別の意味の語。", "ハイパーパラメータは、学習の前に人が設定する調整用の値のことで、属性の推測とは関係がない。"]}'),
  ('g-kentei-i-q38', '10. AI倫理・AIガバナンス',
   '採用選考の判定AIが、学習に使ったデータの集め方に偏りがあったために特定の属性を不利に判定してしまう問題が知られている。このとき「集め方の偏り」に当たる語はどれか。',
   NULL::text,
   '["サンプリングバイアス（データを集める段階で特定の層に偏ってしまうこと）", "過学習（訓練データに合わせすぎて新しいデータに対応できなくなること）", "勾配消失（層を重ねるほど学習の信号が弱まり伝わらなくなること）", "次元の呪い（入力の項目数が増えるほどデータがまばらになり学習が難しくなること）"]',
   0,
   '[0]',
   'single',
   '{"asked": "データを集める段階で生じる偏りを指す語を問う設問。", "point": "集める段階で特定の層に偏るならサンプリングバイアス。", "kid": "学習に使うデータを集めるときに、たまたま偏った人たちばかり集めてしまうこと。集めた後の話ではなく、集める段階で起きる偏り。", "eg": "クラスの好きな給食を調べるのに、たまたまサッカー部の生徒にしか聞かなかったら結果が偏ってしまうのと同じ。聞く相手の選び方自体が偏っていた。", "terms": [["サンプリングバイアス", "データを集める段階で生じる偏り"], ["データの偏り", "収集から学習までのどこかで生じる、集団の実態とデータのずれの総称"]], "think": "なぜ集め方の偏りが判定の偏りにつながるのかがカギ。AIは学習データに映った傾向をそのまま学び取る仕組みなので、学習データの時点である層の人が少ない・多いといった偏りがあると、その層についての判断材料が不足したり過剰になったりする。結果として、少数しか含まれていなかった層に対する判定の精度や公平さが崩れやすくなる。", "vs": "既出の採用AI事例は「結果として偏った判定をした」という現象の話。今回問うのは、その偏りが生まれる原因の一つである「集め方の偏り」の方。過学習・勾配消失・次元の呪いはいずれも学習アルゴリズム側の別の問題で、データの集め方とは関係がない。", "why_asked": "既出の結果側の論点に対し、原因側から理解できているかを問う定番論点。", "usecase": "学習データを集める段階で、特定の属性や集団に偏りがないかを事前に点検する場面。", "opt": ["正解。サンプリングバイアスは、データを集める段階で特定の層に偏ってしまうこと。", "過学習は、訓練データに合わせすぎて新しいデータに対応できなくなることで、データの集め方の偏りとは別の問題。", "勾配消失は、層を重ねるほど学習の信号が弱まり伝わらなくなることで、データの集め方の偏りとは関係がない。", "次元の呪いは、入力の項目数が増えるほどデータがまばらになり学習が難しくなることで、データの集め方の偏りとは別の問題。"]}'),
  ('g-kentei-i-q39', '10. AI倫理・AIガバナンス',
   'システムの安全対策を完成後に付け足すのではなく、企画・設計の最初の段階から組み込んでおく考え方はどれか。',
   NULL::text,
   '["セキュリティ・バイ・デザイン（設計の最初の段階から安全対策を組み込む考え方）", "プライバシー・バイ・デザイン（設計の最初の段階からプライバシーへの配慮を組み込む考え方）", "ペネトレーションテスト（完成したシステムに実際に侵入を試みて弱点を調べる検査）", "インシデント対応マニュアル（事故が起きた後の対応手順をまとめた文書）"]',
   0,
   '[0]',
   'single',
   '{"asked": "設計の最初から安全対策を組み込む考え方の名前を問う設問。", "point": "後付けではなく設計の入口から安全対策を組み込むならセキュリティ・バイ・デザイン。", "kid": "「あとで鍵をつけよう」ではなく、最初の設計図の段階で「ここは守りを固めよう」と決めておく考え方。", "eg": "金庫を作るとき、完成してから扉を厚くするのではなく、最初の設計図に「扉はこの厚さ」と書き込んでおくのに似ている。", "terms": [["セキュリティ・バイ・デザイン", "設計の最初の段階から安全対策を組み込む考え方"]], "think": "なぜ後付けでは弱いのかがカギ。完成したシステムに安全対策を継ぎ足そうとすると、対策できる範囲がシステムの外側の一部に限られ、内部の仕組みに根本的な弱点が残ったままになりやすい。設計の最初から安全性を組み込めば、データの流れや権限の与え方といった内部の仕組みそのものに安全性が織り込まれ、抜け穴が生まれにくくなる。", "vs": "プライバシー・バイ・デザインと並ぶ考え方だが、守る対象が違う。プライバシーは「情報の扱われ方への配慮」、セキュリティは「不正な侵入や攻撃への強さ」。ペネトレーションテストは完成後に行う検査で、設計段階から組み込むという発想とは順番が逆。", "why_asked": "プライバシー・バイ・デザインと並ぶ「〜バイ・デザイン」の考え方として頻出。", "usecase": "新しいシステムの設計段階で、権限管理やデータの流れをあらかじめ安全な形に組み立てる場面。", "opt": ["正解。セキュリティ・バイ・デザインは、企画・設計の最初の段階から安全対策を組み込んでおく考え方。", "プライバシー・バイ・デザインは、設計の最初の段階からプライバシーへの配慮を組み込む考え方で、守る対象が安全性ではなくプライバシーである点が違う。", "ペネトレーションテストは、完成したシステムに実際に侵入を試みて弱点を調べる検査のことで、設計段階から組み込む考え方そのものではない。", "インシデント対応マニュアルは、事故が起きた後の対応手順をまとめた文書のことで、設計の最初から組み込む考え方とは別物。"]}'),
  ('g-kentei-i-q40', '10. AI倫理・AIガバナンス',
   'AIをねらった攻撃には、学習用のデータそのものを盗み出す攻撃や、公開されているAIへの問い合わせを繰り返してモデルの中身を再現してしまう攻撃など、複数の種類がある。後者を指す語はどれか。',
   NULL::text,
   '["モデル窃取（外部からの問い合わせへの応答を繰り返し集め、モデルの中身を再現してしまう攻撃）", "データ窃取（学習に使われているデータそのものを盗み出す攻撃）", "データポイズニング（学習データに悪意のある例を紛れ込ませ学習段階からモデルを狂わせる攻撃）", "敵対的サンプル（入力に人には気づきにくい変化を加えて判定を誤らせる攻撃）"]',
   0,
   '[0]',
   'single',
   '{"asked": "問い合わせの繰り返しでモデルの中身を再現する攻撃の名前を問う設問。", "point": "問い合わせを繰り返して中身を再現するならモデル窃取。", "kid": "AIに何度も質問を送って、返ってきた答えのパターンから「中でどんな計算をしているか」をこっそり真似して作り上げてしまう攻撃。", "eg": "有名店のラーメンを何度も食べに行って味を分析し、レシピを盗んで似た味を再現してしまうのに似ている。お店の中に忍び込まなくても、外から繰り返し試すだけで中身が分かってしまう。", "terms": [["モデル窃取", "問い合わせの繰り返しでモデルの中身を再現する攻撃"], ["データポイズニング", "学習データを汚す攻撃"], ["敵対的サンプル", "入力を細工して誤判定させる攻撃"]], "think": "なぜ問い合わせを繰り返すだけで中身が再現できてしまうのかがカギ。AIモデルは入力に対してある規則性を持った答えを返す仕組みなので、大量の入力と出力の組を集めれば、その規則性を真似た別のモデルを学習させることができてしまう。モデルの中に直接触れなくても、外から見える入出力だけで十分な手がかりになる場合がある。だから公開されたAIへの問い合わせ回数を制限するなどの対策が必要になる。", "vs": "データ窃取は学習データそのものを盗む点でモデル窃取と違う（材料を盗むか、完成品の作り方を盗むかの違い）。データポイズニングは学習の「入力データ」を汚す攻撃、敵対的サンプルは学習済みモデルへの「入力」を細工する攻撃で、いずれも狙う段階と方法がモデル窃取とは異なる。", "why_asked": "既出の敵対的サンプル・データポイズニングとの位置関係を弁別できるかを問う。", "usecase": "自社の学習済みAIをAPIとして公開するとき、問い合わせ回数の制限などの対策を検討する場面。", "opt": ["正解。モデル窃取は、外部からの問い合わせへの応答を繰り返し集め、モデルの中身を再現してしまう攻撃。", "データ窃取は、学習に使われているデータそのものを盗み出す攻撃のことで、モデルの中身を問い合わせから再現する攻撃とは狙う対象が違う。", "データポイズニングは、学習データに悪意のある例を紛れ込ませ学習段階からモデルを狂わせる攻撃のことで、公開後の問い合わせを使う攻撃とは段階が違う。", "敵対的サンプルは、入力に人には気づきにくい変化を加えて判定を誤らせる攻撃のことで、モデルの中身を再現する攻撃とは目的が違う。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\">\n<rect x=\"10\" y=\"55\" width=\"90\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n<text x=\"55\" y=\"74\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">学習データ</text>\n<rect x=\"140\" y=\"55\" width=\"70\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n<text x=\"175\" y=\"74\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">モデル</text>\n<rect x=\"245\" y=\"55\" width=\"90\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.2\"/>\n<text x=\"290\" y=\"74\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">問い合わせ</text>\n<line x1=\"100\" y1=\"70\" x2=\"138\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.2\" marker-end=\"url(#ar)\"/>\n<line x1=\"210\" y1=\"70\" x2=\"243\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.2\" marker-end=\"url(#ar)\"/>\n<defs>\n<marker id=\"ar\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 z\" fill=\"#60a5fa\"/>\n</marker>\n</defs>\n<text x=\"55\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">データ窃取</text>\n<text x=\"55\" y=\"42\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">データポイズニング</text>\n<text x=\"175\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">敵対的サンプル</text>\n<text x=\"175\" y=\"42\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">(入力を細工)</text>\n<path d=\"M290,90 C290,120 100,120 60,90\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.2\" marker-end=\"url(#ar)\"/>\n<text x=\"175\" y=\"132\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c47070\">モデル窃取（問い合わせの繰り返しで中身を再現）</text>\n</svg>"}'),
  ('g-kentei-i-q41', '10. AI倫理・AIガバナンス',
   '生成AIで作られた偽の映像や音声（ディープフェイク）による被害を防ぐため、検知技術の開発に加えて、映像がいつどこで撮影され誰が加工したかを追跡できるようにする取り組みが進められている。この取り組みを指す語として最も適切なものはどれか。',
   NULL::text,
   '["来歴証明（コンテンツがいつどこで作られ、誰がどう加工したかを追跡できるようにする仕組み）", "ウォーターマーク（AIが生成した画像や音声だと分かる目印を埋め込む技術）", "ファクトチェック（発言や記事の内容が事実かどうかを第三者が確認する作業）", "コンテンツモデレーション（投稿されたコンテンツを人手やAIで審査し不適切なものを取り除く運用）"]',
   0,
   '[0]',
   'single',
   '{"asked": "コンテンツの出どころを追跡できるようにする取り組みの名前を問う設問。", "point": "いつどこで作られ誰が加工したかを追跡できる仕組みなら来歴証明。", "kid": "その映像や画像が「いつ、どこで、誰によって作られたか、どう手が加えられたか」を後からたどれるようにしておく取り組み。", "eg": "食品の産地表示に例えると、パッケージを見れば「どこで採れて、どこで加工されたか」がたどれる。映像や画像にも同じような「出どころの記録」を付けようという発想。", "terms": [["来歴証明", "コンテンツの出どころを追跡できるようにする仕組み"], ["ウォーターマーク", "AI生成物と分かる目印を埋め込む技術"]], "think": "なぜ検知技術だけでは不十分なのかがカギ。検知技術は「これは偽物っぽい」と後から見破る力だが、生成技術も日々進化するため見破られない偽物が必ず出てくる。一方で来歴証明は、正しい撮影記録を最初から記録・追跡できるようにしておく仕組みなので、検知をすり抜けられても「記録が無い＝出どころが怪しい」と判断する手がかりになる。両方を組み合わせることで対策の抜け漏れを減らせる。", "vs": "ウォーターマークは来歴証明を実現する手段の一つ（目印を埋め込む技術）。ファクトチェックは内容が事実かを確認する作業で、来歴（誰がどう作ったか）を確認する話とは焦点が違う。コンテンツモデレーションは投稿の審査運用全般を指し、ディープフェイクに限らない広い言葉。", "why_asked": "既出の「ディープフェイクとは」の理解に対し、対応策を理解しているかを問う。", "usecase": "報道機関やSNS事業者が、投稿された映像の出どころを確認できる仕組みを整える場面。", "opt": ["正解。来歴証明は、コンテンツがいつどこで作られ、誰がどう加工したかを追跡できるようにする仕組み。", "ウォーターマークは、AIが生成した画像や音声だと分かる目印を埋め込む技術で、来歴証明を実現する手段の一つにあたる。", "ファクトチェックは、発言や記事の内容が事実かどうかを第三者が確認する作業で、出どころの追跡を目的とする語ではない。", "コンテンツモデレーションは、投稿されたコンテンツを人手やAIで審査し不適切なものを取り除く運用で、出どころの追跡とは焦点が違う。"]}'),
  ('g-kentei-i-q42', '10. AI倫理・AIガバナンス',
   'AIの学習に使うデータについて、それがどこから集められ、どのような加工を経て今の形になったのかを追跡できる状態にしておくことを指す語はどれか。',
   NULL::text,
   '["データの来歴（プロベナンス）（学習データがどこから来てどう加工されたか追跡できる状態）", "データ拡張（手元のデータに変形や加工を加えて水増しし、学習データを増やしていく手法）", "データクレンジング（欠けている値や誤りを取り除き、データを整えていく下準備の作業）", "データリーケージ（本来使えないはずの未来の情報が、学習データに紛れ込んでしまう不具合）"]',
   0,
   '[0]',
   'single',
   '{"asked": "学習データの出どころと加工の履歴を追跡できる状態を指す語を問う設問。", "point": "出どころと加工の履歴を追跡できる状態ならデータの来歴（プロベナンス）。", "kid": "そのデータが「もともとどこで作られて、どんな手を経て今の形になったか」をたどれるようにしておくこと。", "eg": "中古品の来歴書に例えると、「誰が最初に持っていて、どこを経て今の持ち主に来たか」が分かる書類が付いているようなもの。データにも同じように出どころの記録を付けておく。", "terms": [["データの来歴（プロベナンス）", "学習データの出どころと加工の履歴を追跡できる状態"]], "think": "なぜ来歴を追跡できることが重要なのかがカギ。モデルの判定結果に問題が見つかったとき、その原因が学習データのどこにあるかをたどれなければ、直しようがない。来歴が記録されていれば、問題のあるデータがどこから来たのかをさかのぼって特定し、除去や修正につなげられる。だから透明性やモデルへの信頼を支える土台として来歴の管理が求められる。", "vs": "データ拡張（学習データを水増しする技術）、データクレンジング（データを整える作業）、データリーケージ（未来の情報が紛れ込む不具合）はいずれも別の作業・不具合を指す語で、「出どころを追跡できるか」という来歴の話とは別軸。", "why_asked": "透明性を実現する具体的な取り組みとして頻出。", "usecase": "学習データに問題が見つかったとき、その原因をさかのぼって特定する場面。", "opt": ["正解。データの来歴（プロベナンス）は、学習データがどこから来てどう加工されたかを追跡できる状態にすること。", "データ拡張は、手元のデータに変形や加工を加えて水増しし学習データを増やす手法のことで、出どころを追跡する話ではない。", "データクレンジングは、欠けている値や誤りを取り除いてデータを整える作業のことで、出どころを追跡する話ではない。", "データリーケージは、本来使えない未来の情報が学習データに紛れ込んでしまう不具合のことで、出どころを追跡する話ではない。"]}'),
  ('g-kentei-i-q43', '10. AI倫理・AIガバナンス',
   'SNSのアルゴリズムが特定の主張ばかりを繰り返し表示することで利用者の意見が偏り、社会全体でその意見が多数派であるかのように錯覚してしまう現象が、選挙などの意思決定に影響を与えることが懸念されている。この懸念が向けられている社会の仕組みはどれか。',
   NULL::text,
   '["民主主義（多数の人の意見をもとに物事を決める仕組み。意見の偏りが土台を揺るがしかねない）", "資本主義（市場での自由な取引を通じて、お金やモノを社会全体に行き渡らせていく仕組み）", "官僚制（専門知識を持つ職員たちが、組織的なやり方で日々の行政運営を担っていく仕組み）", "三権分立（立法・行政・司法という3つの権力を分けて、互いに厳しく常に抑制し合わせる仕組み）"]',
   0,
   '[0]',
   'single',
   '{"asked": "意見の偏りによって影響を受ける社会の仕組みの名前を問う設問。", "point": "多数の意見をもとに物事を決める仕組みが崩れる懸念なら民主主義。", "kid": "みんなの意見を集めて物事を決める仕組み（選挙など）が、SNSでの意見の偏りによってうまく働かなくなるのではないか、という心配。", "eg": "クラス委員を選ぶとき、たまたま同じ意見の友達とばかり話していると「みんなこう思っているはず」と勘違いしてしまうのに似ている。SNSでも同じことが社会全体の規模で起きてしまう。", "terms": [["エコーチェンバー", "同じ意見ばかりが響き合って増幅される現象"], ["フィルターバブル", "自分の関心に合う情報にばかり囲まれる状態"]], "think": "なぜ意見の偏りが民主主義を揺るがすのかがカギ。民主主義は、様々な意見を持つ人たちが情報を比べて考え、多数決などで物事を決める仕組みが前提になっている。SNSのアルゴリズムが同じ意見ばかりを繰り返し見せると、利用者は他の意見や事実を目にする機会が減り、偏った意見を多数派だと錯覚したまま投票などの意思決定をしてしまう恐れがある。判断の材料がゆがめば、仕組みの前提そのものが崩れてしまう。", "vs": "エコーチェンバー・フィルターバブル（既出）は「意見が偏っていく現象そのもの」を指す語。今回問うのは、その現象が影響を及ぼす先である「社会の仕組み」の方。", "why_asked": "既出のエコーチェンバー/フィルターバブルが社会規模でどう問題を起こすかを理解しているかを問う。", "usecase": "SNS事業者やニュースサービスが、多様な意見を表示する仕組みを検討する場面。", "opt": ["正解。民主主義は、多数の人の意見をもとに物事を決める仕組みで、意見の偏りはこの仕組みの土台を揺るがしかねない。", "資本主義は、市場での自由な取引を通じて資源を配分する仕組みのことで、意見の偏りが直接向けられている懸念の対象ではない。", "官僚制は、専門知識を持つ職員が組織的に行政を担う仕組みのことで、選挙などの意思決定への懸念とは焦点が違う。", "三権分立は、立法・行政・司法の権力を分けて互いに抑制し合う仕組みのことで、意見の偏りへの懸念が直接向けられている対象ではない。"]}'),
  ('g-kentei-i-q44', '10. AI倫理・AIガバナンス',
   'AIが雇用に与える影響をめぐる議論では、「AIと人が協力して働く」「一部の仕事に必要な技能が失われる」「特定の分野で人手が足りなくなる」という複数の論点が指摘されている。このうち、人が積み重ねてきた技能そのものが失われていく懸念を指す語として最も適切なものはどれか。',
   NULL::text,
   '["スキルの喪失（AIに任せる部分が増え、人が技能を身につけ維持する機会を失っていく懸念）", "AIとの協働（人とAIがそれぞれの得意な部分を分担しながら、共に働いていく働き方）", "労働力不足（少子高齢化などが進むことで、働き手そのものが足りなくなっていく状況）", "ベーシックインカム（就労しているかどうかにかかわらず、一定の収入を全員に給付する制度）"]',
   0,
   '[0]',
   'single',
   '{"asked": "技能そのものが失われていく懸念を指す語を問う設問。", "point": "AIに任せる部分が増え人の技能が身につかなくなる懸念ならスキルの喪失。", "kid": "AIに作業を任せる場面が増えるほど、人がその作業を自分の手でやる機会が減り、技能を身につけたり保ち続けたりできなくなっていく心配。", "eg": "電卓に慣れすぎて暗算が苦手になるのに似ている。便利な道具に任せる場面が増えるほど、自分の中の技能が育ちにくくなる。", "terms": [["スキルの喪失", "AIに任せる部分が増えることで人の技能が失われていく懸念"], ["AIとの協働", "人とAIが分担して働く働き方"], ["労働力不足", "働き手そのものが足りなくなる状況"]], "think": "なぜAIとの協働が技能の喪失につながりうるのかがカギ。人は実際に手を動かして経験を積むことで技能を身につけ、維持していく。AIに任せる範囲が広がると、人がその作業を自分でやる回数が減り、経験を積む機会そのものが失われていく。結果として、いざAIに頼れない場面が来たときに対応できる技能が社会から失われている、という事態が起こりうる。", "vs": "AIとの協働は「人とAIが分担して働く」という働き方そのものの話で、スキルの喪失（技能が失われる懸念）とは論点が別。労働力不足は働き手の頭数が足りない状況の話で、技能の話ではない。", "why_asked": "労働政策の3論点（協働・スキルの喪失・労働力不足）を弁別できているかを問う。", "usecase": "企業がAI導入を進める際に、現場の技能継承をどう保つかを検討する場面。", "opt": ["正解。スキルの喪失は、AIに任せる部分が増えることで、人がその作業に必要な技能を身につけ・維持する機会を失っていく懸念。", "AIとの協働は、人とAIがそれぞれの得意な部分を分担して共に働く働き方のことで、技能が失われる懸念そのものを指す語ではない。", "労働力不足は、少子高齢化などにより働き手そのものが足りなくなる状況のことで、技能が失われる懸念とは別の論点。", "ベーシックインカムは、就労の有無にかかわらず一定の収入を全員に給付する制度のことで、技能の喪失とは直接関係がない。"]}'),
  ('g-kentei-i-q45', '10. AI倫理・AIガバナンス',
   'AIサービスを設計するとき、高齢者や障害のある人など特定の利用者だけが恩恵を受けられずに取り残されることがないよう配慮する考え方はどれか。',
   NULL::text,
   '["インクルージョン（誰もがAIの恩恵から取り残されないよう配慮する考え方）", "パーソナライゼーション（利用者一人ひとりの好みに合わせて内容を出し分ける仕組み）", "スケーラビリティ（利用者数の増加に応じてシステムの規模を拡張できる性質）", "ローカライゼーション（サービスを地域の言語や習慣に合わせて調整すること）"]',
   0,
   '[0]',
   'single',
   '{"asked": "特定の利用者が取り残されないよう配慮する考え方の名前を問う設問。", "point": "誰もがAIの恩恵から取り残されないようにするならインクルージョン。", "kid": "どんな人でもAIの恩恵から取り残されないようにしよう、という配慮の考え方。", "eg": "駅にエレベーターやスロープを付けるのに似ている。階段しかないと車椅子の人が使えなくなってしまうので、誰でも使えるように入口を用意しておく。", "terms": [["インクルージョン", "誰もが取り残されないよう配慮する考え方"], ["アクセシビリティ", "高齢者や障害のある人を含め誰もが利用しやすい設計にすること"]], "think": "なぜAIの場面でインクルージョンが特に問題になるのかがカギ。AIは学習データに多く含まれる典型的な利用者に最適化されやすい仕組みのため、操作が複雑な画面や特定の話し方・書き方を前提にしたやり取りなど、少数派の利用者が置き去りにされる設計になりがちである。だから設計段階で「取り残される人がいないか」を意識的に確認する考え方が必要になる。", "vs": "パーソナライゼーションは「一人ひとりに合わせて出し分ける」技術面の仕組みで、インクルージョンの「誰も取り残さない」という配慮の考え方とは目的が違う。スケーラビリティ・ローカライゼーションはいずれもシステムの技術的な性質を指す語で、利用者への配慮とは別軸。", "why_asked": "AI倫理の「その他の重要な価値」の代表として頻出。", "usecase": "サービスの画面設計で、高齢者や障害のある人でも使える操作方法を用意する場面。", "opt": ["正解。インクルージョンは、誰もがAIの恩恵から取り残されないよう配慮する考え方。", "パーソナライゼーションは、利用者一人ひとりの好みに合わせて内容を出し分ける仕組みのことで、取り残しを防ぐ配慮そのものを指す語ではない。", "スケーラビリティは、利用者数の増加に応じてシステムの規模を拡張できる性質のことで、利用者への配慮とは別の技術的な性質。", "ローカライゼーションは、サービスを地域の言語や習慣に合わせて調整することで、取り残される人への配慮とは別の観点。"]}'),
  ('g-kentei-i-q46', '10. AI倫理・AIガバナンス',
   '人間が最終的な判断に関与せず、AIが自律的に攻撃対象を選び攻撃を実行する兵器システムをめぐっては、国際的な議論が続いている。この兵器システムを指す語はどれか。',
   NULL::text,
   '["自律型致死兵器システム（人間の関与なしにAIが自律的に攻撃対象を選び攻撃を実行する兵器）", "サイバー防衛システム（ネットワークへの不正な侵入や攻撃を、常に検知して防いでいく仕組み）", "監視衛星システム（宇宙から地上のあらゆる様子を、継続的に観測し続けていくための仕組み）", "早期警戒レーダー（空から飛来してくる物体を、できるだけ早く探知するための観測装置）"]',
   0,
   '[0]',
   'single',
   '{"asked": "人間の関与なしに攻撃を実行する兵器システムの名前を問う設問。", "point": "人間の関与なしにAIが自律的に攻撃を実行するなら自律型致死兵器システム。", "kid": "人が最後の判断をせずに、AIが自分で「誰を攻撃するか」を決めて実行してしまう兵器のこと。", "eg": "見張り番に例えると、普通の見張り番は「怪しい人がいます」と報告して人間が撃つかどうかを決める。今回の兵器は、見張り番自身が判断して撃ってしまう、という違いがある。", "terms": [["自律型致死兵器システム", "人間の関与なしにAIが自律的に攻撃を実行する兵器"]], "think": "なぜ議論になるのかがカギ。人間が最終判断に関わらないまま攻撃が実行されると、誤った判断による被害が起きたときに誰が責任を負うのかがあいまいになり、判断基準がブラックボックスのまま重大な結果を招く恐れがある。人間の判断がどこまで関与すべきかという論点が、国際的な議論の中心になっている。", "vs": "サイバー防衛システム・監視衛星システム・早期警戒レーダーはいずれも「情報を集める・守る」ための仕組みで、「攻撃を自律的に実行するかどうか」という論点そのものとは焦点が違う。", "why_asked": "AI倫理の「その他の重要な価値」の代表として頻出。", "usecase": "国際会議でAI兵器の規制ルールを議論する場面。", "opt": ["正解。自律型致死兵器システムは、人間の関与なしにAIが自律的に攻撃対象を選び攻撃を実行する兵器。", "サイバー防衛システムは、ネットワークへの不正な侵入や攻撃を検知し防御する仕組みのことで、自律的に攻撃を実行する兵器とは別物。", "監視衛星システムは、宇宙から地上の様子を継続的に観測する仕組みのことで、攻撃を実行する兵器とは別物。", "早期警戒レーダーは、飛来する物体をいち早く探知する装置のことで、攻撃を自律的に実行する兵器そのものではない。"]}'),
  ('g-kentei-i-q47', '10. AI倫理・AIガバナンス',
   'AIで故人の声や姿を再現して生前のように話させる技術や、AIが提示するおすすめに沿って利用者が次第に自分で考えず行動を決めるようになる懸念は、公平性や透明性とは別の論点として議論されている。これらが関わる論点はどれか。',
   NULL::text,
   '["死者への敬意・人間の自律性（故人の再現や、AIへの依存で判断する力が損なわれる懸念）", "説明可能性（AIの判断がどのような根拠に基づくかを、人間が理解できる形で示すこと）", "データ汚染（学習データに悪意のある例が紛れ込むことで、モデルが狂わされてしまうこと）", "モデルの軽量化（計算資源が少ない環境でも動くように、モデルを小さくしていく技術）"]',
   0,
   '[0]',
   'single',
   '{"asked": "故人の再現やAI依存の懸念が関わる論点を問う設問。", "point": "故人の再現やAI依存への懸念は死者への敬意・人間の自律性の論点。", "kid": "亡くなった人をAIで再現していいのかという問題や、AIに頼りすぎて自分で考えなくなってしまう心配。公平さや説明のしやすさとはまた別の、もっと根っこの価値観に関わる話。", "eg": "故人の写真を加工して動かすアルバムに例えると、思い出として大切にする分にはよくても、まるで生きているかのように扱われ続けると、遺族や本人の尊厳をどう考えるかという難しい問題が出てくる。", "terms": [["人間の自律性", "自分で考え判断する力が損なわれないようにするという価値観"], ["死者への敬意", "故人をAIで再現することの是非をめぐる論点"]], "think": "なぜこれらが「その他の重要な価値」として別枠で議論されるのかがカギ。公平性や透明性は「AIの判断が正しく・分かりやすいか」という論点だが、故人の再現や依存の問題は、そもそも「AIにそこまでやらせてよいのか」「人が自分で決める力を保てているか」という、正しさとは別の価値観に関わる論点であるため、独立した論点として扱われる。", "vs": "説明可能性（AIの判断根拠を示せるか）やデータ汚染（学習データが狂わされる問題）、モデルの軽量化（技術的な効率化）は、いずれも今回の「死者への敬意」「人間の自律性」とは別の論点を指す語。", "why_asked": "AI倫理の「その他の重要な価値」の代表として頻出。", "usecase": "故人を再現するサービスを企画するとき、遺族の意向や本人の尊厳をどう扱うか検討する場面。", "opt": ["正解。死者への敬意・人間の自律性は、故人の再現や、AIへの依存によって自分で判断する力が損なわれることをめぐる論点。", "説明可能性は、AIの判断根拠を人間が理解できる形で示せるようにすることで、故人の再現や依存の懸念そのものを指す語ではない。", "データ汚染は、学習データに悪意のある例が紛れ込みモデルが狂わされることで、故人の再現や依存の懸念とは別の技術的な問題。", "モデルの軽量化は、計算資源の少ない環境でも動くようにモデルを小さくする技術のことで、今回の論点とは関係がない。"]}'),
  ('g-kentei-i-q48', '10. AI倫理・AIガバナンス',
   'AIサービスをリリースする前に、想定される倫理上のリスクを洗い出して点検し、必要に応じて第三者にも確認してもらう取り組みを指す語として最も適切なものはどれか。',
   NULL::text,
   '["倫理アセスメント（リリース前に倫理上のリスクを洗い出して点検する取り組み）", "ユーザビリティテスト（利用者にとっての使いやすさを実際に確認していく検査）", "負荷テスト（大量のアクセスが一度に集中したときの動作を確認していく検査）", "A/Bテスト（一部の利用者に異なる案を出し分けて成果を比べていく方法）"]',
   0,
   '[0]',
   'single',
   '{"asked": "リリース前に倫理上のリスクを点検する取り組みの名前を問う設問。", "point": "リリース前に倫理上のリスクを洗い出して点検するなら倫理アセスメント。", "kid": "サービスを世に出す前に、「このAIは誰かを不当に不利に扱わないか」「偏りはないか」といった倫理面の問題を洗い出して点検しておく取り組み。", "eg": "新しい薬を発売する前に安全性の審査を受けるのに似ている。効果があっても、副作用や危険がないかを事前にチェックしてから世に出す。", "terms": [["倫理アセスメント", "リリース前に倫理上のリスクを点検する取り組み"], ["AIに対する監査", "第三者がAIの仕組みや運用を確認する取り組み"]], "think": "なぜリリース前の点検が必要なのかがカギ。倫理上の問題（特定の層への偏った判定など）は、通常の機能テストでは見つかりにくく、リリース後に利用者が実際に不利益を受けて初めて表面化することが多い。事前に倫理アセスメントを行い、必要なら開発者以外の第三者にも確認してもらうことで、問題を世に出す前に見つけて手を打てる。", "vs": "ユーザビリティテスト・負荷テスト・A/Bテストはいずれも品質や成果を確認するための別の検査手法で、「倫理上のリスクがないか」という観点そのものを点検するものではない。", "why_asked": "AIガバナンスの実務として頻出。", "usecase": "新しい採用選考AIをリリースする前に、偏りや不利益がないか事前に確認する場面。", "opt": ["正解。倫理アセスメントは、リリース前に倫理上のリスクを洗い出して点検する取り組みで、第三者による確認を含むこともある。", "ユーザビリティテストは、利用者にとっての使いやすさを確認する検査のことで、倫理上のリスクの点検そのものを指す語ではない。", "負荷テストは、大量のアクセスが集中したときの動作を確認する検査のことで、倫理上のリスクの点検とは焦点が違う。", "A/Bテストは、一部の利用者に異なる案を出し分けて成果を比べる方法のことで、倫理上のリスクの点検とは目的が違う。"]}'),
  ('g-kentei-i-q49', '10. AI倫理・AIガバナンス',
   '企業が全社共通のAI利用ルールを明文化し、多様な立場のメンバーを検討に加え、重要な判断には人間の関与を確保するといった体制を整える取り組みはどれか。',
   NULL::text,
   '["AIポリシーと組織体制の整備（全社共通のルールを明文化し人間の関与を確保する体制づくり）", "セキュリティ・バイ・デザイン（設計の最初の段階から、安全対策をあらかじめ組み込んでいく考え方）", "品質マネジメントシステム（製品やサービスの品質を、継続的に管理し続けていくための仕組み）", "コーポレートガバナンスコード（企業統治のあり方を示す、上場企業向けの行動指針や原則）"]',
   0,
   '[0]',
   'single',
   '{"asked": "全社共通のAI利用ルールと体制を整える取り組みの名前を問う設問。", "point": "全社共通のルールを明文化し人間の関与を確保する体制づくりならAIポリシーと組織体制の整備。", "kid": "会社全体で「AIをどう使うか」のルールを文章にしてはっきりさせ、いろいろな立場の人に検討に加わってもらい、大事な判断には必ず人が関わるようにする体制を整えること。", "eg": "会社の就業規則に例えると、口約束ではなく文書にしてルールを明文化しておくことで、誰が見ても同じ基準で判断できるようになる。AI利用ルールも同じように文章にして共有しておく。", "terms": [["AIポリシー", "全社共通のAI利用ルールを明文化したもの"], ["ダイバーシティ", "検討に多様な立場のメンバーを加えること"]], "think": "なぜ明文化と多様なメンバーの関与が必要なのかがカギ。ルールが担当者の頭の中にしかないと、担当者が変わるたびに判断がぶれてしまう。文章にして共有しておけば誰が担当しても同じ基準で判断できる。また、開発に関わる人だけで検討すると気づけない偏りやリスクがあるため、立場の異なるメンバーを加え、重要な判断には必ず人が関与する体制にすることで、見落としを減らす。", "vs": "セキュリティ・バイ・デザインは設計段階の考え方、品質マネジメントシステムは品質管理の仕組み、コーポレートガバナンスコードは上場企業向けの企業統治の原則で、いずれもAI倫理に特化した組織体制の話とは焦点が異なる。", "why_asked": "AIガバナンスを実現する組織的な取り組みとして頻出。", "usecase": "全社でAIを導入する前に、利用ルールを文書化し検討メンバーをそろえる場面。", "opt": ["正解。AIポリシーと組織体制の整備は、全社共通のAI利用ルールを明文化し、多様な視点や人間の関与を確保する体制づくり。", "セキュリティ・バイ・デザインは、設計の最初の段階から安全対策を組み込む考え方のことで、全社的な組織体制の整備とは焦点が違う。", "品質マネジメントシステムは、製品やサービスの品質を継続的に管理する仕組みのことで、AI倫理に特化した組織体制とは別物。", "コーポレートガバナンスコードは、企業統治のあり方を示す上場企業向けの原則のことで、AI利用ルールの明文化そのものを指す語ではない。"]}'),
  ('g-kentei-i-q50', '10. AI倫理・AIガバナンス',
   'AIガバナンスの実務では、運用中のAIを継続的に監視すること、同じ条件なら同じ結果が得られること、そして判断に至った経緯を後から追えることの3点が重視される。この3点の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["モニタリング・再現性・トレーサビリティ（継続監視、同じ結果の再現、経緯の追跡の3点）", "スケーラビリティ・可用性・保守性（規模拡張、止まりにくさ、直しやすさという技術面の3点）", "精度・再現率・適合率（判定の正しさを測るための評価指標の3点）", "開発・検証・展開（AIプロジェクトを進めていく工程の3段階）"]',
   0,
   '[0]',
   'single',
   '{"asked": "AIガバナンス実務で重視される3点の組み合わせを問う設問。", "point": "継続監視・同じ結果の再現・経緯の追跡の3点ならモニタリング・再現性・トレーサビリティ。", "kid": "AIを世に出した後も、「ちゃんと見張り続けること」「同じ条件ならいつも同じ結果になること」「なぜその判断になったか後からたどれること」の3つを整えておくこと。", "eg": "飛行機のフライトレコーダーに例えると、飛行中はずっと状態を記録し（モニタリング）、同じ操作をすれば同じ動きになるよう整備されていて（再現性）、事故があれば記録を見返して原因をたどれる（トレーサビリティ）。この3つがそろって初めて安全に運用できる。", "terms": [["モニタリング", "運用中のAIを継続的に監視すること"], ["再現性", "同じ条件なら同じ結果が得られること"], ["トレーサビリティ", "判断に至った経緯を後から追えること"]], "think": "なぜこの3点が組み合わせで重視されるのかがカギ。運用中に精度が落ちても気づけなければ手遅れになるためモニタリングが要る。監視で異常に気づいても、同じ条件で同じ結果を再現できなければ原因の切り分けができないため再現性が要る。そして原因が分かっても、その判断がどのデータや処理を経て出てきたのかを後からたどれなければ、根本原因の特定や説明ができないためトレーサビリティが要る。3つがそろって初めて、運用中のAIを適切に管理できる。", "vs": "スケーラビリティ・可用性・保守性はシステムの技術的な性質、精度・再現率・適合率は評価指標、開発・検証・展開はプロジェクトの工程で、いずれも今回問うガバナンス実務の3点とは別の分類。", "why_asked": "AIガバナンスの実務3点として頻出。", "usecase": "運用中のAIサービスで、監視ダッシュボードや判断ログの記録の仕組みを整える場面。", "opt": ["正解。モニタリング・再現性・トレーサビリティは、継続的な監視、同じ結果が得られること、経緯を後から追えることの3点。", "スケーラビリティ・可用性・保守性は、規模を拡張できる性質、止まりにくい性質、直しやすい性質という技術的な3点で、ガバナンス実務の3点とは分類が違う。", "精度・再現率・適合率は、判定の正しさを測る評価指標の3点で、ガバナンス実務の3点とは分類が違う。", "開発・検証・展開は、AIプロジェクトを進める工程の3段階で、運用後のガバナンス実務の3点とは分類が違う。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-i'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
